const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeMenindee = ee.Geometry.Point([142.4, -32.3]).buffer(20000); // 20km buffer around Lake Menindee

  const date1 = '2017-01-27';
  const date2 = '2019-02-02';

  // 2. Data Acquisition - Sentinel-2
  function getWaterImage(date) {
    const col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(lakeMenindee)
      .filterDate(date, ee.Date(date).advance(1, 'month'));

    if (col.size().getInfo() === 0) {
      return null;
    }

    // Cloud masking function
    function maskS2clouds(image) {
      const qa = image.select('QA60');
      const cloudBitMask = 1 << 10;
      const cirrusBitMask = 1 << 11;
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
          .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return image.updateMask(mask);
    }

    const maskedCol = col.map(maskS2clouds);
    const composite = maskedCol.median();

    // Calculate NDWI for water detection
    const ndwi = composite.normalizedDifference(['B3', 'B8']).rename('NDWI');

    // Water mask (NDWI > 0)
    const waterMask = ndwi.gt(0);

    return waterMask;
  }

  // Get images for both dates
  const water2017 = getWaterImage(date1);
  const water2019 = getWaterImage(date2);

  // Check for empty collections
  if (!water2017 || !water2019) {
    console.log("2017 Images: " + (water2017 ? "Available" : "None"));
    console.log("2019 Images: " + (water2019 ? "Available" : "None"));
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Calculate water areas
  function calculateWaterArea(waterMask) {
    const areaImage = waterMask.multiply(ee.Image.pixelArea()); // Area in m²

    const stats = areaImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: lakeMenindee,
      scale: 30,
      maxPixels: 1e9
    });

    const area = stats.get('NDWI');
    const pixelCount = waterMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: lakeMenindee,
      scale: 30,
      maxPixels: 1e9
    }).get('NDWI');

    return {area: area, pixelCount: pixelCount};
  }

  const area2017 = calculateWaterArea(water2017);
  const area2019 = calculateWaterArea(water2019);

  const area2017Val = area2017.area.getInfo();
  const area2019Val = area2019.area.getInfo();
  const pixels2017 = area2017.pixelCount.getInfo();
  const pixels2019 = area2019.pixelCount.getInfo();

  // Check for no valid pixels
  if (pixels2017 === 0 || pixels2019 === 0) {
    console.log(`2017 Pixels: ${pixels2017}, 2019 Pixels: ${pixels2019}`);
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure
  if (area2017Val === null || area2019Val === null || 
      isNaN(area2017Val) || isNaN(area2019Val) ||
      area2017Val < 0 || area2019Val < 0) {
    console.log(`2017 Area: ${area2017Val}, 2019 Area: ${area2019Val}`);
    console.log("<answer>C3</answer>");
    return;
  }

  // 4. Determine if lake shrank
  const area2017Km2 = area2017Val / 1000000; // Convert to km²
  const area2019Km2 = area2019Val / 1000000;
  const shrinkage = ((area2017Km2 - area2019Km2) / area2017Km2) * 100;

  console.log(`2017 Area: ${area2017Km2.toFixed(2)} km² (Pixels: ${pixels2017})`);
  console.log(`2019 Area: ${area2019Km2.toFixed(2)} km² (Pixels: ${pixels2019})`);
  console.log(`Change: ${shrinkage.toFixed(1)}%`);

  // Consider shrinkage > 5% as significant
  if (shrinkage > 5) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
